using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;
// Optional calibrated panel-edge detector. No idle-text timeout is used.
public sealed class DialogDetector{
 [DllImport("user32.dll")]static extern bool PrintWindow(IntPtr window,IntPtr dc,uint flags);
 int captureWidth,captureHeight;Bitmap reference;DateTime last=DateTime.MinValue;bool? candidate,reported;DateTime changed;Rectangle roi;
 public void Reset(){if(reference!=null)reference.Dispose();reference=null;candidate=null;reported=null;}
 static Bitmap Capture(IntPtr window,int width,int height,Rectangle region){using(var image=new Bitmap(width,height,PixelFormat.Format32bppArgb)){if(!GameCapture.Into(window,image,2))return null;return image.Clone(region,PixelFormat.Format32bppArgb);}}
 public bool Calibrate(IntPtr window,int width,int height,double x,double y,double w,double h){Reset();int left=Math.Max(0,Math.Min(width-8,(int)(width*x/100))),top=Math.Max(0,Math.Min(height-8,(int)(height*y/100)));roi=new Rectangle(left,top,Math.Max(8,Math.Min(width-left,(int)(width*w/100))),Math.Max(8,Math.Min(height-top,(int)(height*h/100))));reference=Capture(window,width,height,roi);if(reference==null)return false;int low=255,high=0;for(int py=0;py<reference.Height;py+=Math.Max(1,reference.Height/8))for(int px=0;px<reference.Width;px+=Math.Max(1,reference.Width/24)){var p=reference.GetPixel(px,py);int l=(p.R+p.G+p.B)/3;low=Math.Min(low,l);high=Math.Max(high,l);}if(high-low<8){Reset();return false;}captureWidth=width;captureHeight=height;return true;}
 public bool? Tick(IntPtr window,int width,int height){if(reference!=null&&(width!=captureWidth||height!=captureHeight)){Reset();return true;}if(reference==null||(DateTime.UtcNow-last).TotalMilliseconds<400||roi.Right>width||roi.Bottom>height)return null;last=DateTime.UtcNow;using(var image=Capture(window,width,height,roi)){if(image==null)return null;double difference=0;int count=0;for(int y=0;y<image.Height;y+=Math.Max(1,image.Height/12))for(int x=0;x<image.Width;x+=Math.Max(1,image.Width/24)){var a=image.GetPixel(x,y);var b=reference.GetPixel(x,y);difference+=(Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B))/3.0;count++;}bool visible=difference/Math.Max(1,count)<18;if(candidate!=visible){candidate=visible;changed=DateTime.UtcNow;}if((DateTime.UtcNow-changed).TotalMilliseconds>=800&&reported!=visible){reported=visible;return visible;}return null;}}
}
